<form id="loginForm">
  <label for="username">Enter your username:</label>
  <input type="text" id="username" name="username" required>

  <label for="password">Enter your password:</label>
  <input type="password" id="password" name="password" required>

  <button type="submit">Login</button>
</form>
<div id="loginResult" style="display: none; padding: 10px; background-color: #f9f9f9; border: 1px solid #ccc; font-size: 14px; color: #333; margin-top: 10px;"></div>

<script>
  document.getElementById('loginForm').addEventListener('submit', function(event) {
    event.preventDefault();
    const username = document.getElementById('username').value;
    const password = document.getElementById('password').value;

    if (!username || !password) {
      document.getElementById('loginResult').textContent = 'Please enter your username and password.';
      return;
    }

    document.getElementById('loginResult').textContent = 'Login successful!';
    document.getElementById('loginForm').reset();
  });
</script>
```

This code creates a basic login form with placeholders for the username and password fields. It includes a submit button and a modal for displaying success messages. You can customize the placeholder values as needed.
